class EventStore {
  constructor() {
    this.events = [];
  }

  append(event) {
    this.events.push(event);
  }

  replay() {
    return this.events.reduce((state, event) => {
      switch (event.type) {
        case 'USER_CREATED':
          state.users.push(event.payload);
          break;

        default:
          break;
      }

      return state;
    }, {
      users: []
    });
  }
}

