class ConcurrencyController {
  constructor(limit) {
    this.limit = limit;
    this.running = 0;
    this.queue = [];
  }

  async run(task) {
    if (this.running >= this.limit) {
      await new Promise((resolve) => {
        this.queue.push(resolve);
      });
    }

    this.running++;

    try {
      return await task();
    } finally {
      this.running--;

      const next = this.queue.shift();

      if (next) {
        next();
      }
    }
  }
}

