function rankResults(results, keyword) {
  return results
    .map((result) => {
      const score = result.content
        .toLowerCase()
        .split(keyword.toLowerCase())
        .length - 1;

      return {
        ...result,
        score
      };
    })
    .sort((a, b) => {
      return b.score - a.score;
    });
}

